import{_ as d,o as e,c as a,a2 as r}from"./chunks/framework.CHeM0PsO.js";const m=JSON.parse('{"title":"对话语法","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agent/syntax.md","filePath":"guide/agent/syntax.md","lastUpdated":1789295632000}'),o={name:"guide/agent/syntax.md"};function c(n,t,h,i,l,s){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="对话语法" tabindex="-1">对话语法 <a class="header-anchor" href="#对话语法" aria-label="Permalink to &quot;对话语法&quot;">​</a></h1><p>与智能体对话时（你和角色的气泡内），排版语法与站内帖子<strong>不同</strong>：对话气泡支持 GitHub 风格 Markdown（GFM）和安全范围内的 HTML；帖子等站内位置使用的 MFM 不会作用于对话气泡。</p><h2 id="markdown-gfm" tabindex="-1">Markdown（GFM） <a class="header-anchor" href="#markdown-gfm" aria-label="Permalink to &quot;Markdown（GFM）&quot;">​</a></h2><p>对话气泡支持以下语法（角色输出也遵循同样规则）：</p><table tabindex="0"><thead><tr><th>语法</th><th>效果</th></tr></thead><tbody><tr><td><code># 标题</code> <code>## 二级标题</code></td><td>标题</td></tr><tr><td><code>**加粗**</code></td><td>加粗</td></tr><tr><td><code>*斜体*</code></td><td>斜体</td></tr><tr><td><code>~~删除线~~</code></td><td>删除线</td></tr><tr><td><code>`行内代码`</code></td><td>行内代码</td></tr><tr><td><code>- 列表项</code>（可嵌套）</td><td>无序列表</td></tr><tr><td><code>1. 第一项</code></td><td>有序列表</td></tr><tr><td><code>&gt; 引用内容</code></td><td>引用块</td></tr><tr><td><code>[链接文字](URL)</code></td><td>超链接</td></tr><tr><td>| 列 A | 列 B | 形式</td><td>表格</td></tr><tr><td><code>```js …代码… ```</code></td><td>带语言高亮的代码块</td></tr><tr><td><code>- [x] 已完成</code> / <code>- [ ] 未完成</code></td><td>任务清单</td></tr><tr><td>直接换行</td><td>软换行（同一气泡内换行显示）</td></tr></tbody></table><p>完整规范见 <a href="https://github.github.com/gfm/" target="_blank" rel="noreferrer">GFM 规范</a>。</p><h2 id="安全的-html" tabindex="-1">安全的 HTML <a class="header-anchor" href="#安全的-html" aria-label="Permalink to &quot;安全的 HTML&quot;">​</a></h2><p>对话气泡同时支持安全范围内的 HTML 标签（如 <code>&lt;b&gt;</code>、<code>&lt;i&gt;</code>）。<code>&lt;script&gt;</code> 等脚本和事件属性等危险内容会被自动过滤移除。</p><h2 id="表情与贴纸" tabindex="-1">表情与贴纸 <a class="header-anchor" href="#表情与贴纸" aria-label="Permalink to &quot;表情与贴纸&quot;">​</a></h2><table tabindex="0"><thead><tr><th>写法</th><th>说明</th></tr></thead><tbody><tr><td><code>:表情名:</code></td><td>全站自定义表情，嵌入正文内联显示。用户和角色都可以发送；聊天输入框的表情按钮可直接插入</td></tr><tr><td><code>[[agent_sticker key=标识]]</code></td><td>角色专属表情包。由角色发出，单独占一行，以统一大小的方形贴纸图块展示；开启分段输出时独占一个气泡</td></tr></tbody></table><p>角色专属表情包由创作者在角色编辑页配置（图片 + 使用时机描述），角色根据对话情绪自主选择发送。详见<a href="/guide/agent/regex-stickers#角色表情包">正则与表情包</a>。</p><h2 id="手动触发世界书" tabindex="-1">手动触发世界书 <a class="header-anchor" href="#手动触发世界书" aria-label="Permalink to &quot;手动触发世界书&quot;">​</a></h2><p>在消息里写 <code>[[wb:条目标题]]</code> 或 <code>[[wb:条目ID]]</code>，可以直接点名触发对应的世界书条目（即使关键词没命中）。详见<a href="/guide/agent/worldbook">世界书</a>。</p><h2 id="mfm-呢" tabindex="-1">MFM 呢？ <a class="header-anchor" href="#mfm-呢" aria-label="Permalink to &quot;MFM 呢？&quot;">​</a></h2><p>MFM（站内帖子用的富文本语法，如 <code>$[x2 放大]</code>）<strong>不在对话气泡内生效</strong>。想在帖子里用动画效果，参见 <a href="/guide/misskey/mfm">MFM 语法</a>。</p>',15)])])}const g=d(o,[["render",c]]);export{m as __pageData,g as default};
